31	/**
32	 * 遏制逾期升级服务测试：覆盖期限确定、检查触发/不触发、确认权限与状态边界、
33	 * 交接期间权限、遏制原子取消、失败回滚与 commandKey 幂等语义。
34	 * 使用可控 Clock，时间相关断言不依赖真实睡眠。
35	 */
36	@SpringBootTest
37	@Import(ControllableClock.Config.class)
38	class EscalationServiceTest {
39	
40	    private static final Instant T0 = Instant.parse("2026-09-22T00:00:00Z");
41	
42	    @Autowired
43	    private IncidentService service;
44	
45	    @Autowired
46	    private JdbcTemplate jdbc;
47	
48	    @Autowired
49	    private Clock clock;
50	
51	    @BeforeEach
52	    void clean() {
53	        jdbc.update("DELETE FROM command_keys");
54	        jdbc.update("DELETE FROM incident_escalations");
55	        jdbc.update("DELETE FROM incident_status_history");
56	        jdbc.update("DELETE FROM incident_transfers");
57	        jdbc.update("DELETE FROM incident_actions");
58	        jdbc.update("DELETE FROM incidents");
59	        ((ControllableClock) clock).setInstant(T0);
60	    }
61	
62	    private static String key() {
63	        return "CMD-" + UUID.randomUUID();
64	    }
65	
66	    private IncidentView setup(String incidentKey, String severity, String commander) {
67	        service.report(new ReportRequest(incidentKey, severity, "核心链路故障", "reporter-1"));
68	        return service.takeover(incidentKey, commander, new TakeoverRequest(key()));
69	    }
70	
71	    private static void assertApiStatus(ThrowingCallable call, HttpStatus status) {
72	        assertThatThrownBy(call).isInstanceOfSatisfying(ApiException.class,
73	                e -> assertThat(e.status()).isEqualTo(status));
74	    }
75	
76	    @Test
77	    void deadline_setAtTakeover_bySeverity_andNotResetByTransfer() {
78	        Map<String, Long> minutes = Map.of("S1", 5L, "S2", 15L, "S3", 60L, "S4", 240L);
79	        int n = 0;
80	        for (Map.Entry<String, Long> e : minutes.entrySet()) {
81	            String ik = "INC-DL-" + n++;
82	            IncidentView commanding = setup(ik, e.getKey(), "alice");
83	            Instant expected = T0.plus(e.getValue(), ChronoUnit.MINUTES);
84	            assertThat(commanding.deadlineAt()).isEqualTo(expected);
85	            // REPORTED 阶段无期限
86	            service.report(new ReportRequest(ik + "-R", e.getKey(), "x", "r"));
87	            assertThat(service.get(ik + "-R").deadlineAt()).isNull();
88	
89	            // 交接不重置期限
90	            service.initiateTransfer(ik, "alice", new TransferRequest(key(), "bob"));
91	            service.acceptTransfer(ik, "bob", new TransferAcceptRequest(key()));
92	            assertThat(service.get(ik).deadlineAt()).isEqualTo(expected);
93	        }
94	    }
95	
96	    @Test
97	    void check_beforeDeadline_noRecord_andQueryDoesNotWrite() {
98	        setup("INC-E-001", "S1", "alice");
99	        ((ControllableClock) clock).setInstant(T0.plusSeconds(299));
100	        EscalationHistoryView view = service.checkEscalation("INC-E-001",
101	                new EscalationCheckRequest(key()));
102	        assertThat(view.current()).isNull();
103	        assertThat(view.history()).isEmpty();
104	        assertThat(view.deadlineAt()).isEqualTo(T0.plus(5, ChronoUnit.MINUTES));
105	        // GET 查询不得隐式写入
106	        EscalationHistoryView queried = service.escalationHistory("INC-E-001");
107	        assertThat(queried.current()).isNull();
108	        Integer rows = jdbc.queryForObject(
109	                "SELECT COUNT(*) FROM incident_escalations WHERE incident_id ="
110	                        + " (SELECT id FROM incidents WHERE incident_key='INC-E-001')",
111	                Integer.class);
112	        assertThat(rows).isZero();
113	    }
114	
115	    @Test
116	    void check_beforeDeadline_sameKeyReplay_neverReevaluates() {
117	        setup("INC-E-002", "S1", "alice");
118	        ((ControllableClock) clock).setInstant(T0.plusSeconds(60));
119	        String commandKey = key();
120	        EscalationHistoryView first = service.checkEscalation("INC-E-002",
121	                new EscalationCheckRequest(commandKey));
122	        assertThat(first.current()).isNull();
123	        // 时钟越过期限后同键重放仍返回首次（无记录）结果，不重新评估
124	        ((ControllableClock) clock).setInstant(T0.plus(10, ChronoUnit.MINUTES));
125	        EscalationHistoryView replay = service.checkEscalation("INC-E-002",
126	                new EscalationCheckRequest(commandKey));
127	        assertThat(replay).isEqualTo(first);
